	@Test
	void rawForeignAndMutableWriterScansDoNotReuseManagedPages() throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(2, 64), true); Txn reader = fixture.snapshot()) {
			Set<Q> original = Set.copyOf(fixture.quads);
			warmScans(fixture, reader, "psoc");
			try (CodecWork work = new CodecWork()) {
				assertThat(read(fixture, reader, false, "psoc", UNBOUND, null))
						.containsExactlyElementsOf(expected(original, "psoc", UNBOUND, null, null));
				assertThat(work.walks).as("a raw handle does not authorize shared snapshot reuse").isPositive();
			}
			try (Txn foreign = fixture.store.getTxnManager().createTxn(reader.get());
					CodecWork work = new CodecWork()) {
				assertThat(foreign.isReadOnly()).isFalse();
				assertThat(read(fixture, foreign, true, "psoc", UNBOUND, null))
						.containsExactlyElementsOf(expected(original, "psoc", UNBOUND, null, null));
				assertThat(work.walks).as("foreign wrappers cannot borrow managed immutable pages").isPositive();
			}
			fixture.store.startTransaction();
			try (Txn writer = fixture.store.getTxnManager().createTxn(fixture.store.writeTxn)) {
				Q changed = quad(16, 20);
				fixture.remove(changed);
				fixture.adjacency.compact(fixture.store.writeTxn, true);
				try (CodecWork work = new CodecWork()) {
					assertThat(read(fixture, writer, true, "psoc", UNBOUND, null))
							.containsExactlyElementsOf(expected(fixture.quads, "psoc", UNBOUND, null, null));
					assertThat(work.walks).as("a writer validates its current physical pages").isPositive();
				}
				fixture.add(changed);
				fixture.adjacency.compact(fixture.store.writeTxn, true);
				assertThat(read(fixture, writer, true, "psoc", UNBOUND, null))
						.containsExactlyElementsOf(expected(original, "psoc", UNBOUND, null, null));
			}
			fixture.store.rollback();
			assertThat(read(fixture, reader, true, "psoc", UNBOUND, null))
					.containsExactlyElementsOf(expected(original, "psoc", UNBOUND, null, null));
		}
	}

	@Test
	void warmUnboundScansCannotBypassRetiredReaderGuards() throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(2, 64), true); Txn reader = fixture.snapshot()) {
			warmScans(fixture, reader, "psoc");
			long lease = reader.lease();
			long nativeId = reader.nativeTransactionId();
			try (RecordIterator retained = fixture.adjacency.scan(reader, -1, -1, -1, -1, true, "psoc")) {
				reader.close();
				assertThatThrownBy(() -> read(fixture, reader, true, "psoc", UNBOUND, null))
						.isInstanceOf(SailException.class)
						.hasMessageContaining("closed");
				assertThatThrownBy(retained::next).isInstanceOf(SailException.class).hasMessageContaining("closed");
				try (Txn recycled = fixture.snapshot()) {
					assertThat(recycled).as("the RESET pool reuses the retired wrapper").isSameAs(reader);
					assertThat(recycled.lease()).isGreaterThan(lease);
					assertThat(recycled.nativeTransactionId()).isEqualTo(nativeId);
					assertThat(read(fixture, recycled, true, "psoc", UNBOUND, null))
							.containsExactlyElementsOf(expected(fixture.quads, "psoc", UNBOUND, null, null));
					assertThatThrownBy(retained::next).isInstanceOf(SailException.class)
							.hasMessageContaining("recycled");
					try (RecordIterator invalidated = fixture.adjacency.scan(recycled, -1, -1, -1, -1, true,
							"psoc")) {
						fixture.store.getTxnManager().deactivate();
						fixture.store.getTxnManager().activate();
						assertThatThrownBy(() -> read(fixture, recycled, true, "psoc", UNBOUND, null))
								.isInstanceOf(LmdbSailStore.MapResizeConflictException.class);
						assertThatThrownBy(invalidated::next)
								.isInstanceOf(LmdbSailStore.MapResizeConflictException.class);
					}
				}
			}
		}
	}

	@ParameterizedTest(name = "pinned={0}")
	@ValueSource(booleans = { false, true })
	void warmScansFollowTheirOwnSnapshotThroughCompactionAndRenewal(boolean pinned) throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(2, 256), true);
				Txn reader = pinned ? fixture.snapshot() : fixture.store.getTxnManager().createReadTxn()) {
			Set<Q> original = Set.copyOf(fixture.quads);
			warmScans(fixture, reader, "opsc");
			try (RecordIterator records = fixture.adjacency.scan(reader, -1, -1, -1, -1, true, "opsc")) {
				List<Q> initial = prefix(records, 160);
				assertThat(initial).containsExactlyElementsOf(expected(original, "opsc", UNBOUND, null, null)
						.subList(0, initial.size()));
				Q last = initial.get(initial.size() - 1);
				Q changed = quad(200, 21);
				fixture.store.startTransaction();
				fixture.remove(changed);
				fixture.add(new Q(changed.s() + 1, changed.p(), changed.o(), changed.c()));
				fixture.adjacency.compact(fixture.store.writeTxn, true);
				fixture.store.commit();
				if (!pinned) {
					fixture.store.getTxnManager().deactivate();
					fixture.store.getTxnManager().activate();
				}
				assertThat(collect(records)).containsExactlyElementsOf(after(pinned ? original : fixture.quads,
						"opsc", last));
			}
			try (Txn current = fixture.snapshot()) {
				assertThat(read(fixture, current, true, "opsc", UNBOUND, null))
						.containsExactlyElementsOf(expected(fixture.quads, "opsc", UNBOUND, null, null));
				assertThat(read(fixture, reader, true, "opsc", UNBOUND, null))
						.containsExactlyElementsOf(expected(pinned ? original : fixture.quads, "opsc", UNBOUND,
								null, null));
			}
		}
	}

	@Test
	void returnedQuadsAndBatchesCannotMutateSharedPageColumns() throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(2, 160), true); Txn reader = fixture.snapshot()) {
			List<Q> all = expected(fixture.quads, "spoc", UNBOUND, null, null);
			warmScans(fixture, reader, "spoc");
			try (RecordIterator records = fixture.adjacency.scan(reader, -1, -1, -1, -1, true, "spoc")) {
				long[] first = records.next();
				assertThat(Q.of(first)).isEqualTo(all.get(0));
				Arrays.fill(first, -123);
				long[] batch = new long[16];
				assertThat(records.fill(batch, 4)).isEqualTo(4);
				for (int index = 0; index < 4; index++) {
					assertThat(Q.of(Arrays.copyOfRange(batch, index * 4, index * 4 + 4)))
							.isEqualTo(all.get(index + 1));
				}
				Arrays.fill(batch, -456);
				assertThat(collect(records)).containsExactlyElementsOf(all.subList(5, all.size()));
			}
			assertThat(read(fixture, reader, true, "spoc", UNBOUND, null)).containsExactlyElementsOf(all);
		}
	}

	@Test
	void malformedReplacementNeverReusesAnOlderSnapshotPage() throws Exception {
		try (LmdbPersistentAdjacencyManagedPointCacheTest.Fixture fixture = new LmdbPersistentAdjacencyManagedPointCacheTest.Fixture(
				directory, 1,
				PersistentCsfPageCodec.MAX_PAIRS, false);
				Txn old = fixture.snapshot()) {
			List<Q> original = fixture.model.stream()
					.map(value -> new Q(value.s(), value.p(), value.o(), value.c()))
					.toList();
			for (int repeat = 0; repeat < 2; repeat++) {
				assertThat(scan(fixture.adjacency, old, "psoc"))
						.containsExactlyElementsOf(expected(original, "psoc", UNBOUND, null, null));
			}
			PersistentCsfPointFixtures.Images images = PersistentCsfPointFixtures.corruption("late-neighbor");
			fixture.replacePage(images.corrupted());
			try (Txn malformed = fixture.snapshot(); CodecWork work = new CodecWork()) {
				assertThat(malformed.nativeTransactionId()).isNotEqualTo(old.nativeTransactionId());
				for (int attempt = 0; attempt < 2; attempt++) {
					assertThatThrownBy(() -> scan(fixture.adjacency, malformed, "psoc"))
							.isInstanceOf(SailException.class)
							.hasRootCauseMessage("Malformed persistent CSF page: "
									+ "neighbors are not strictly unsigned ascending");
				}
				assertThat(work.walks).as("failed full validation cannot publish a ready page").isEqualTo(2);
			}
			assertThat(scan(fixture.adjacency, old, "psoc"))
					.containsExactlyElementsOf(expected(original, "psoc", UNBOUND, null, null));
		}
	}

	@Test
	void scanAndPointPagesShareOneGlobalTuplePayloadBudget() throws Exception {
		try (Fixture fixture = new Fixture(directory, sharedRows(12, 1024), true); Txn reader = fixture.snapshot()) {
			assertThat(fixture.physicalFences(reader, fixture.adjacency.pagesDbi(), "spoc")).hasSize(12);
			assertThat(fixture.physicalFences(reader, fixture.adjacency.pagesDbi(), "opsc")).hasSize(12);
			for (int predicate = 0; predicate < 12; predicate++) {
				for (int repeat = 0; repeat < 2; repeat++) {
					assertPoint(fixture, reader, quad(8, 20 + predicate));
				}
			}
			warmScans(fixture, reader, "opsc");
			try (CodecWork work = new CodecWork()) {
				for (int predicate = 0; predicate < 12; predicate++) {
					assertPoint(fixture, reader, quad(8, 20 + predicate));
				}
				// Twenty-four 1024-tuple pages exceed 512 KiB: at most 21 can remain READY across both uses.
				assertThat(work.walks).as("scan pages consume the same global payload budget as point pages")
						.isGreaterThanOrEqualTo(3);
			}
		}
	}

	private static void warmScans(Fixture fixture, Txn reader, String order) throws Exception {
		for (int repeat = 0; repeat < 2; repeat++) {
			assertThat(read(fixture, reader, true, order, UNBOUND, null))
					.containsExactlyElementsOf(expected(fixture.quads, order, UNBOUND, null, null));
		}
	}

	private static void assertPoint(Fixture fixture, Txn reader, Q quad) throws Exception {
		try (RecordIterator records = fixture.adjacency.scan(reader, quad.s(), quad.p(), quad.o(), quad.c(), true,
				"psoc")) {
			assertThat(Q.of(records.next())).isEqualTo(quad);
			assertThat(records.next()).isNull();
		}
	}

	private static List<Q> scan(LmdbPersistentAdjacency adjacency, Txn reader, String order) throws Exception {
		try (RecordIterator records = adjacency.scan(reader, -1, -1, -1, -1, true, order)) {
			return collect(records);
		}
	}

	private static boolean incoming(String order) {
		return order.equals("posc") || order.equals("opsc");
	}
